const state={csrf:'',user:null,health:null,resources:[],performanceLatest:{},connections:[],alerts:[],tasks:[],audit:[],users:[],selectedResourceId:null,selectedResourceSource:null,bulkSelection:new Set(),pending:null,refreshing:false,sessionPolicy:{idleTimeoutMs:30*60_000,absoluteTimeoutMs:8*60*60_000},lastActivityAt:Date.now(),sessionWarningShown:false};const titles={overview:'Platform overview',inventory:'Virtual machines',connections:'Provider connections',alerts:'Connection alerts',tasks:'Task activity',audit:'Audit history',users:'User administration',health:'Platform health'};
async function api(path,options={}){const headers={...(options.body?{'content-type':'application/json'}:{}),...(options.headers??{})};if(options.method&&options.method!=='GET')headers['x-csrf-token']=state.csrf;const r=await fetch(`/api/v1${path}`,{...options,headers});if(r.status===401&&!options.public){showLogin();throw Error('Session expired');}const data=r.status===204?null:await r.json();if(!r.ok)throw Error(data?.detail??'Request failed');if(data?.sessionPolicy)state.sessionPolicy=data.sessionPolicy;return data;}
