$('reset-form').addEventListener('submit',async e=>{e.preventDefault();$('reset-error').textContent='';const submit=e.currentTarget.querySelector('button[type="submit"],button:not([type])');if(submit?.disabled)return;if(submit)submit.disabled=true;try{const values=Object.fromEntries(new FormData(e.currentTarget));values.username=String(values.username??'').trim();values.recoveryCode=String(values.recoveryCode??'').trim();const result=await api('/auth/password-reset',{method:'POST',public:true,body:JSON.stringify(values)});showRecoveryCode(result.recoveryCode,'Password reset successfully. Save this new recovery code; it replaces the code you just used.');$('login-form').username.value=values.username;e.currentTarget.reset();showAuthPanel('login-panel');$('login-form').password.focus()}catch(error){$('reset-error').textContent=error.message}finally{if(submit)submit.disabled=false}});

$('logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}finally{document.querySelector('.account-menu').open=false;state.csrf='';state.user=null;showLogin()}};$('recovery-code').onclick=async()=>{document.querySelector('.account-menu').open=false;try{const result=await api('/auth/recovery-code',{method:'POST'});showRecoveryCode(result.recoveryCode,'A new lab recovery code was generated. Any previous code is now invalid.')}catch(error){notice(error.message,'error')}};document.addEventListener('click',event=>{const menu=document.querySelector('.account-menu');if(menu?.open&&!menu.contains(event.target))menu.open=false});

async function showSessions(){document.querySelector('.account-menu').open=false;const result=await api('/auth/sessions'),minutes=Math.round(result.sessionPolicy.idleTimeoutMs/60_000);$('session-policy').textContent=`Sessions close after ${minutes} minutes of inactivity. The current session is identified below.`;$('session-list').innerHTML=result.items.map(session=>`<article class="session-item"><span aria-hidden="true">${session.current?'●':'○'}</span><div><strong>${session.current?'Current session':'Signed-in session'}</strong><small>Last active ${when(session.lastSeenAt)} · expires ${when(session.idleExpiresAt)}</small></div><button data-revoke-session="${session.id}">${session.current?'Sign out':'Revoke'}</button></article>`).join('')||'<div class="empty compact">No active sessions.</div>';$('sessions-dialog').showModal()}
async function showDiagnostics(connectionId){const result=await api(`/connections/${connectionId}/diagnostics`),connection=result.connection,failureDetail=connection.consecutiveFailures?` · ${connection.consecutiveFailures} consecutive failure${connection.consecutiveFailures===1?'':'s'}`:'';$('diagnostics-title').textContent=`Diagnostics · ${connection.name}`;$('diagnostics-summary').innerHTML=`<div><span>Health</span><strong>${esc(connection.healthState)}${esc(failureDetail)}</strong></div><div><span>Last successful sync</span><strong>${when(connection.lastSyncAt)}</strong></div><div><span>${connection.nextRetryAt?'Next automatic retry':'Inventory'}</span><strong>${connection.nextRetryAt?when(connection.nextRetryAt):(result.stale?'Stale or not synchronized':'Current')}</strong></div>`;$('diagnostics-list').innerHTML=result.items.map(item=>`<article class="session-item ${item.outcome==='succeeded'?'diagnostic-good':'diagnostic-bad'}"><span aria-hidden="true">${item.outcome==='succeeded'?'✓':'!'}</span><div><strong>${esc(item.checkType.replaceAll('_',' '))} · ${esc(item.outcome)}</strong><small>${when(item.checkedAt)} · ${item.durationMs} ms${item.errorCode?` · ${esc(item.errorCode)}`:''}</small></div></article>`).join('')||'<div class="empty compact"><strong>No diagnostics recorded</strong><p>Run Test or Discover to create the first health event.</p></div>';$('diagnostics-dialog').showModal()}
$('my-sessions').onclick=()=>showSessions().catch(error=>notice(error.message,'error'));$('sessions-close').onclick=()=>$('sessions-dialog').close();$('session-list').addEventListener('click',async event=>{const button=event.target.closest('[data-revoke-session]');if(!button)return;try{await api(`/auth/sessions/${button.dataset.revokeSession}`,{method:'DELETE'});if(button.textContent==='Sign out'){state.csrf='';state.user=null;$('sessions-dialog').close();showLogin();return}await showSessions();notice('Session revoked.')}catch(error){notice(error.message,'error')}});
