for(const eventName of ['pointerdown','keydown','touchstart'])document.addEventListener(eventName,()=>{state.lastActivityAt=Date.now();state.sessionWarningShown=false;document.querySelector('.session-warning')?.remove()},{passive:true});setInterval(async()=>{if($('application').hidden||!state.user)return;const remaining=state.sessionPolicy.idleTimeoutMs-(Date.now()-state.lastActivityAt);if(remaining<=0){try{await api('/auth/logout',{method:'POST'})}catch{}state.csrf='';state.user=null;showLogin();return}if(remaining<=5*60_000&&!state.sessionWarningShown){state.sessionWarningShown=true;document.body.insertAdjacentHTML('beforeend',`<div class="session-warning" role="alert">Your session will close in about ${Math.max(1,Math.ceil(remaining/60_000))} minute${remaining>60_000?'s':''} due to inactivity.</div>`)}},30_000);

async function load(){const permissions=state.user?.permissions??[],canManageUsers=permissions.includes('identity.manage'),canViewAudit=permissions.includes('audit.view'),[health,connections,alerts,resources,latestMetrics,tasks,audit,users]=await Promise.all([api('/health'),api('/connections'),api('/connection-alerts?limit=100'),api('/resources?resourceType=virtual_machine'),api('/performance/latest'),api('/tasks'),canViewAudit?api('/audit-events?limit=100'):Promise.resolve({items:[]}),canManageUsers?api('/users'):Promise.resolve({items:[]})]);Object.assign(state,{health,connections:connections.items,alerts:alerts.items,resources:resources.items,performanceLatest:Object.fromEntries(latestMetrics.items.map(item=>[item.resourceId,item])),tasks:tasks.items,audit:audit.items,users:users.items});render()}
async function refreshProviders(){if(state.refreshing)return;state.refreshing=true;const buttons=[$('refresh'),$('inventory-refresh')].filter(Boolean);buttons.forEach(button=>button.disabled=true);try{const enabled=state.connections.filter(connection=>connection.status==='enabled'),results=await Promise.allSettled(enabled.map(connection=>api(`/connections/${connection.id}/discover`,{method:'POST'})));await load();const failed=results.filter(result=>result.status==='rejected');if(failed.length)notice(`Inventory refreshed with ${failed.length} connection failure${failed.length===1?'':'s'}.`,'error');else notice(`Inventory refreshed across ${enabled.length} connection${enabled.length===1?'':'s'}.`);}catch(error){notice(error.message,'error')}finally{state.refreshing=false;buttons.forEach(button=>button.disabled=false)}}
function setConsoleControls(enabled){for(const id of ['console-ctrl-alt-del','console-key','console-send-key','console-scale'])$(id).disabled=!enabled}
function consoleFullscreenElement(){return document.fullscreenElement||document.webkitFullscreenElement}
async function toggleConsoleFullscreen(){const dialog=$('console-dialog'),target=dialog.firstElementChild;if(consoleFullscreenElement()){const exit=document.exitFullscreen||document.webkitExitFullscreen;if(exit)await exit.call(document);return}const request=target?.requestFullscreen||target?.webkitRequestFullscreen;if(!request)throw new Error('Fullscreen is not supported by this browser.');await request.call(target)}
function syncConsoleFullscreenButton(){$('console-fullscreen').textContent=consoleFullscreenElement()?'Exit fullscreen':'Fullscreen'}
function sendConsoleChord(keys){const console=state.console;if(!console)return;for(const key of keys)console.sendKey(key.keysym,key.code,true);for(const key of [...keys].reverse())console.sendKey(key.keysym,key.code,false);console.focus()}
function sendConsoleSpecialKey(name){const keys={escape:[{keysym:0xff1b,code:'Escape'}],tab:[{keysym:0xff09,code:'Tab'}],enter:[{keysym:0xff0d,code:'Enter'}],'ctrl-escape':[{keysym:0xffe3,code:'ControlLeft'},{keysym:0xff1b,code:'Escape'}],'ctrl-alt-insert':[{keysym:0xffe3,code:'ControlLeft'},{keysym:0xffe9,code:'AltLeft'},{keysym:0xff63,code:'Insert'}],'alt-f4':[{keysym:0xffe9,code:'AltLeft'},{keysym:0xffc1,code:'F4'}],meta:[{keysym:0xffeb,code:'MetaLeft'}]};if(/^f([1-9]|1[0-2])$/.test(name)){const number=Number(name.slice(1));return sendConsoleChord([{keysym:0xffbd+number,code:`F${number}`}])}if(keys[name])sendConsoleChord(keys[name])}
async function openConsole(resource){const dialog=$('console-dialog'),screen=$('console-screen'),status=$('console-status');state.consoleResource=resource;setConsoleControls(false);screen.replaceChildren();status.hidden=false;status.innerHTML='<div><strong>Connecting to VM console…</strong><small>Establishing a secure display session.</small></div>';$('console-title').textContent=`Console · ${resource.name}`;$('console-scale').textContent='Actual size';if(!dialog.open)dialog.showModal();try{const session=await api(`/resources/${resource.id}/console-sessions`,{method:'POST'}),{default:RFB}=await import('/vendor/novnc/core/rfb.js'),scheme=location.protocol==='https:'?'wss':'ws',socketUrl=`${scheme}://${location.host}${session.consoleUrl}`;state.console=new RFB(screen,socketUrl,{shared:true,wsProtocols:['binary']});state.console.scaleViewport=true;state.console.focusOnClick=true;const timer=setTimeout(()=>{status.hidden=false;status.innerHTML='<div><strong>Console connection timed out</strong><small>Close the console and try again.</small></div>'},30000);state.console.addEventListener('credentialsrequired',()=>{if(session.credential?.password)return state.console.sendCredentials({password:session.credential.password});const password=window.prompt('Enter the VMware Workstation VNC password for this VM.');if(password!==null)state.console.sendCredentials({password});else state.console.disconnect()});state.console.addEventListener('connect',()=>{clearTimeout(timer);status.hidden=true;setConsoleControls(true);state.console.focus();notice(`Console connected to ${resource.name}.`)});state.console.addEventListener('disconnect',event=>{clearTimeout(timer);setConsoleControls(false);if(!event.detail.clean){status.hidden=false;status.innerHTML='<div><strong>Unable to display the VM console</strong><small>The provider display session ended. Close the console and try again.</small></div>';notice('Console connection failed.','error')}});}catch(error){setConsoleControls(false);status.innerHTML=`<div><strong>Unable to open console</strong><small>${esc(error.message)}</small></div>`;notice(error.message,'error')}}
function openHostTerminal(connectionId){const connection=state.connections.find(item=>item.id===connectionId),dialog=$('terminal-dialog'),screen=$('terminal-screen'),status=$('terminal-status'),terminal=new globalThis.Terminal({cursorBlink:true,convertEol:true,fontFamily:'ui-monospace,SFMono-Regular,Menlo,Consolas,monospace',fontSize:13,theme:{background:'#000000',foreground:'#d7e0e2',cursor:'#5fd3c7'}}),fit=new globalThis.FitAddon.FitAddon();screen.replaceChildren();status.hidden=true;$('terminal-title').textContent=`Host Terminal · ${connection?.name??'ESXi'}`;dialog.showModal();terminal.loadAddon(fit);terminal.open(screen);fit.fit();terminal.focus();state.terminal={socket:null,terminal,fit};state.terminalResize=()=>fit.fit();window.addEventListener('resize',state.terminalResize);terminal.writeln('\x1b[1;36mNuvrion ESXi Host Terminal\x1b[0m');terminal.writeln('Enter an ESXi SSH account. Credentials are used for this session only and are not saved.\r\n');let stage='username',username='',password='',connecting=false;terminal.write('Username: ');const connect=async()=>{connecting=true;terminal.write('\r\nConnecting to ESXi…\r\n');const credential={username,password};password='';try{const session=await api(`/connections/${connectionId}/terminal-sessions`,{method:'POST',body:JSON.stringify(credential)});credential.password='';const scheme=location.protocol==='https:'?'wss':'ws',socket=new WebSocket(`${scheme}://${location.host}${session.socketUrl}`);state.terminal.socket=socket;terminal.onResize(({cols,rows})=>{if(socket.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'resize',cols,rows}))});socket.onmessage=event=>{const message=JSON.parse(event.data);if(message.type==='output')terminal.write(message.data);if(message.type==='status'&&message.state==='connected'){terminal.writeln('\x1b[1;32mConnected.\x1b[0m');fit.fit();terminal.focus()}if(message.type==='error')terminal.writeln(`\r\n\x1b[1;31m${message.message}\x1b[0m`)};socket.onclose=()=>{if(dialog.open)terminal.writeln('\r\n\x1b[33mTerminal session closed.\x1b[0m')};socket.onerror=()=>terminal.writeln('\r\n\x1b[1;31mUnable to establish the secure terminal connection.\x1b[0m')}catch(error){credential.password='';terminal.writeln(`\r\n\x1b[1;31mUnable to open terminal: ${error.message}\x1b[0m`);notice(error.message,'error')}};terminal.onData(data=>{const socket=state.terminal?.socket;if(connecting){if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'input',data}));return}for(const char of data){if(char==='\r'){if(stage==='username'){if(!username.trim()){terminal.write('\r\nUsername: ');continue}stage='password';terminal.write('\r\nPassword\x3a ')}else if(password){connect();break}else terminal.write('\r\nPassword\x3a ')}else if(char==='\u007f'){if(stage==='username'&&username){username=username.slice(0,-1);terminal.write('\b \b')}else if(stage==='password'&&password)password=password.slice(0,-1)}else if(char>=' '&&char!=='\u007f'){if(stage==='username'&&username.length<128){username+=char;terminal.write(char)}else if(stage==='password'&&password.length<1024)password+=char}}})}
