const metricValue=(value,suffix='')=>value==null?'—':`${Number(value).toLocaleString(undefined,{maximumFractionDigits:1})}${suffix}`;
const byteValue=value=>value==null?'—':`${(Number(value)/1073741824).toLocaleString(undefined,{maximumFractionDigits:1})} GB`;
const vmHostname=resource=>resource.providerMetadata?.hostName??resource.providerMetadata?.hostname??resource.providerMetadata?.computerName??resource.providerMetadata?.privateDnsName??'Unknown';
