function metricIcon(type){const icons={cpu:'<svg viewBox="0 0 32 32" aria-hidden="true"><rect x="5" y="5" width="22" height="22" rx="2" fill="#62b84c"/><rect x="9" y="9" width="14" height="14" fill="url(#cpu-g)" stroke="#d9f3d3"/><path d="M2 9h4M2 15h4M2 21h4M26 9h4M26 15h4M26 21h4M9 2v4M15 2v4M21 2v4M9 26v4M15 26v4M21 26v4" stroke="#4b9d3c"/><defs><linearGradient id="cpu-g" x1="9" y1="9" x2="23" y2="23"><stop stop-color="#f6fbf5"/><stop offset="1" stop-color="#9cafac"/></linearGradient></defs></svg>',memory:'<svg viewBox="0 0 38 26" aria-hidden="true"><rect x="2" y="5" width="34" height="15" rx="2" fill="#75b94f"/><rect x="6" y="8" width="6" height="8" fill="#596b9d"/><rect x="16" y="8" width="6" height="8" fill="#596b9d"/><rect x="26" y="8" width="6" height="8" fill="#596b9d"/><path d="M7 20v4M13 20v4M19 20v4M25 20v4M31 20v4" stroke="#b6a24a" stroke-width="2"/></svg>',storage:'<svg viewBox="0 0 30 34" aria-hidden="true"><ellipse cx="15" cy="6" rx="11" ry="4" fill="#eee" stroke="#777"/><path d="M4 6v9c0 2 5 4 11 4s11-2 11-4V6M4 15v9c0 2 5 4 11 4s11-2 11-4v-9" fill="#c9c9c9" stroke="#777"/><ellipse cx="15" cy="15" rx="11" ry="4" fill="#ddd" stroke="#777"/><ellipse cx="15" cy="24" rx="11" ry="4" fill="#ccc" stroke="#777"/></svg>'};return icons[type]}
function metricChart(title,samples,key){const values=samples.map(sample=>sample[key]).filter(value=>value!=null).map(Number);if(values.length<2)return `<section class="metric-chart"><h3>${esc(title)}</h3><div class="empty compact"><p>Not enough history yet.</p></div></section>`;const max=Math.max(...values,1),points=values.map((value,index)=>`${index/(values.length-1)*100},${100-value/max*90}`).join(' ');return `<section class="metric-chart"><h3>${esc(title)}</h3><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="${esc(title)} history"><polyline points="${points}"/></svg></section>`}
async function showPerformance(resourceId){state.performanceResourceId=resourceId;const resource=state.resources.find(item=>item.id===resourceId);$('performance-title').textContent=`Performance · ${resource?.name??'Virtual machine'}`;$('performance-current').replaceChildren();$('performance-charts').replaceChildren();$('performance-empty').hidden=true;$('performance-source').textContent='Loading provider measurements…';if(!$('performance-dialog').open)$('performance-dialog').showModal();try{const hours=Number($('performance-range').value),result=await api(`/resources/${resourceId}/metrics?hours=${hours}`),latest=result.latest,samples=result.items??[];if(!result.available||!latest){$('performance-source').textContent='No provider measurements received.';$('performance-empty').hidden=false;return}$('performance-source').textContent=`Source: ${String(latest.source).replaceAll('_',' ')} · observed ${when(latest.observedAt)}`;$('performance-current').innerHTML=[['CPU',latest.cpuUtilizationPercent!=null?metricValue(latest.cpuUtilizationPercent,'%'):metricValue(latest.cpuUsageMhz,' MHz')],['Memory',latest.memoryUtilizationPercent!=null?metricValue(latest.memoryUtilizationPercent,'%'):byteValue(latest.memoryUsedBytes)],['Storage used',byteValue(latest.storageUsedBytes)],['Network',latest.networkRxBytesPerSec==null&&latest.networkTxBytesPerSec==null?'—':`${metricValue(latest.networkRxBytesPerSec,' B/s')} ↓ · ${metricValue(latest.networkTxBytesPerSec,' B/s')} ↑`]].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('');$('performance-charts').innerHTML=metricChart('CPU utilization',samples,'cpuUtilizationPercent')+metricChart('Memory utilization',samples,'memoryUtilizationPercent')}catch(error){$('performance-source').textContent=error.message;$('performance-empty').hidden=false}}
function renderOverview(){const m=state.health?.metrics??{},active=state.resources.filter(r=>r.lifecycleState==='active'),running=active.filter(r=>r.attributes.powerState==='running').length,critical=state.alerts.filter(a=>a.severity==='critical'&&['active','acknowledged'].includes(a.status)).length;$('global-health').textContent=state.health?.status??'Unknown';$('global-health').className='badge good';$('summary-cards').innerHTML=[['Virtual machines',m.resourcesActive??active.length,'Active across connected providers','▦'],['Running',running,'Powered on','▶'],['Open tasks',(m.tasksQueued??0)+(m.tasksRunning??0),'Queued or executing','◷'],['Critical alerts',critical,critical?'Requires attention':'No critical incidents','⚠']].map(x=>`<article class="metric-card"><span class="metric-icon">${x[3]}</span><div><p>${x[0]}</p><strong>${x[1]}</strong><small>${x[2]}</small></div></article>`).join('');const groups=Object.entries(active.reduce((a,r)=>(a[r.providerType]=(a[r.providerType]??0)+1,a),{}));$('estate-summary').innerHTML=active.length?`<div class="donut" style="--value:${Math.round(running/active.length*100)}"><span>${active.length}<small>Active</small></span></div><div class="legend">${groups.map(([p,n])=>`<div><span></span><strong>${esc(provider(p))}</strong><em>${n} VM${n===1?'':'s'}</em></div>`).join('')}</div>`:'<div class="empty compact"><strong>No inventory yet</strong><p>Add a connection to begin discovery.</p></div>';$('recent-tasks').innerHTML=state.tasks.slice(0,5).map(t=>`<div><span class="activity-icon">${t.operation==='stop'?'■':'▶'}</span><p><strong>${esc(t.operation)} · ${esc(resourceName(t.target.id))}</strong><small>${when(t.completedAt??t.queuedAt)}</small></p>${badge(t.status)}</div>`).join('')||'<div class="empty compact"><p>No task activity.</p></div>'}
