async function loadExpandedVmMetrics(resourceId){const target=$('vm-performance-summary');if(!target)return;try{const result=await api(`/resources/${resourceId}/metrics?hours=1`);if(state.selectedResourceId!==resourceId||!$('vm-performance-summary'))return;target.innerHTML=result.available&&result.items?.length?metricChart('CPU utilization / ready',result.items,'cpuUtilizationPercent'):'<div class="empty compact"><p>No performance history reported by this provider.</p></div>'}catch(error){target.innerHTML=`<div class="empty compact"><p>${esc(error.message)}</p></div>`}}
const renderInventoryBase=renderInventory;
renderInventory=function(){renderInventoryBase();const canOperate=(state.user?.permissions??[]).includes('resource.operate'),selected=state.resources.find(resource=>resource.id===state.selectedResourceId),expanded=Boolean(selected&&state.selectedResourceSource==='sidebar');if(!selected){$('vm-action-toolbar').innerHTML=bulkToolbar(canOperate);return}const consoleEnabled=canOperate&&['vmware_vsphere','vmware_workstation'].includes(selected.providerType)&&selected.attributes.powerState==='running';$('vm-action-toolbar').innerHTML=`<button class="vm-toolbar-action console" ${consoleEnabled?`data-console="${selected.id}"`:'disabled'}><span>▣</span>Console</button>${canOperate?toolbarAction(selected,'start','▶','Power on')+toolbarAction(selected,'stop','■','Shut down')+toolbarAction(selected,'pause','Ⅱ','Suspend')+toolbarAction(selected,'restart','↻','Restart'):''}<button class="vm-toolbar-action edit" data-edit-vm="${selected.id}"><span>✎</span>Edit</button><button class="vm-toolbar-action refresh" data-refresh-vms><span>↻</span>Refresh</button><button class="vm-toolbar-action actions" data-vm-actions="${selected.id}"><span>⚙</span>Actions</button>`;if(expanded){$('vm-detail').querySelector('.vm-detail-panels')?.remove();$('vm-detail').insertAdjacentHTML('beforeend',expandedSections(selected,state.performanceLatest[selected.id]??{}));loadExpandedVmMetrics(selected.id)}};
function renderConnections(){const permissions=state.user?.permissions??[],canManage=permissions.includes('connection.manage'),canOperate=permissions.includes('resource.operate'),canManagePlatform=permissions.includes('platform.manage');$('connection-list').innerHTML=state.connections.map(c=>{const hostActions=c.providerType==='vmware_vsphere'&&c.connectionType==='esxi'?`${canOperate?`<button data-host-client="${c.id}">Open Host Client</button>`:''}${canManagePlatform?`<button data-host-terminal="${c.id}">Host Terminal</button>`:''}`:'',management=canManage?`<button data-diagnostics="${c.id}">Diagnostics</button><button data-test-connection="${c.id}">Test</button><button data-discover="${c.id}" class="primary">Discover</button>`:'',resourceCount=state.resources.filter(r=>r.connectionId===c.id&&r.lifecycleState==='active').length;return `<article class="connection-card"><div class="provider-logo">${c.providerType==='aws'?'AWS':c.providerType==='azure'?'AZ':'VM'}</div><div class="connection-main"><div><h3>${esc(c.name)}</h3>${badge(c.healthState)}</div><p>${esc(provider(c.providerType))}</p><small>${esc(c.endpointUri??'Managed endpoint')}</small><div class="connection-meta"><span>Resources<strong>${resourceCount}</strong></span><span>Last sync<strong>${c.lastSyncAt?when(c.lastSyncAt):'Not synced'}</strong></span></div></div><div class="connection-actions">${hostActions}${management}</div></article>`}).join('')||'<article class="card empty"><strong>No connections configured</strong><p>Add your first infrastructure endpoint.</p></article>'}
function renderAlerts(){const canManage=(state.user?.permissions??[]).includes('connection.manage'),active=state.alerts.filter(a=>['active','acknowledged'].includes(a.status)),critical=active.filter(a=>a.severity==='critical').length;$('alerts-empty').hidden=!!state.alerts.length;$('alert-summary').textContent=active.length?`${active.length} active · ${critical} critical`:'No active alerts';$('alert-summary').className=`badge ${critical?'bad':active.length?'warn':'good'}`;$('alert-table').innerHTML=state.alerts.map(a=>`<tr><td>${when(a.openedAt)}</td><td><strong>${esc(a.connectionName??state.connections.find(c=>c.id===a.connectionId)?.name??a.connectionId)}</strong><small class="block">Last seen ${when(a.lastSeenAt)}</small></td><td>${badge(a.severity)}</td><td>${badge(a.status)}</td><td><code>${esc(a.errorCode)}</code></td><td>${a.occurrenceCount}</td><td class="row-actions right">${canManage&&a.status==='active'?`<button data-ack-alert="${a.id}" class="primary small">Acknowledge</button>`:'—'}</td></tr>`).join('')}
function renderTasks(){const canOperate=(state.user?.permissions??[]).includes('resource.operate');$('task-table').innerHTML=state.tasks.map(t=>{const action=canOperate&&(t.status==='queued'?['cancel','Cancel']:t.status==='failed'?['retry','Retry']:t.status==='verification_required'?['reconcile','Reconcile']:null),button=action?`<button data-task-action="${action[0]}" data-task-id="${t.id}" class="${action[0]==='cancel'?'danger-link':''}">${action[1]}</button>`:'—';return `<tr><td><strong class="capitalize">${esc(t.operation)}</strong></td><td>${esc(resourceName(t.target.id))}</td><td>${esc(t.requestedBy?.username??'System')}</td><td>${badge(t.status)}</td><td>${when(t.startedAt??t.queuedAt)}</td><td><code>${esc(t.correlationId?.slice(0,8))}…</code></td><td class="row-actions right">${button}</td></tr>`}).join('')}
function renderAudit(){$('audit-table').innerHTML=state.audit.map(e=>`<tr><td>${when(e.occurredAt)}</td><td>${esc(e.actorName??'System')}</td><td><strong>${esc(e.action)}</strong></td><td>${esc(resourceName(e.targetId))}</td><td>${badge(e.outcome)}</td><td><code>${esc(e.correlationId?.slice(0,8))}…</code></td></tr>`).join('')}
