function renderHealth(){const c=state.health?.components??{};$('health-components').innerHTML=Object.entries(c).map(([n,v])=>`<article class="health-card"><span class="health-check">✓</span><div><p>${esc(n.replace(/([A-Z])/g,' $1'))}</p><strong>${esc(v)}</strong></div>${badge(v==='healthy'?'healthy':'connected')}</article>`).join('');$('platform-metrics').innerHTML=Object.entries(state.health?.metrics??{}).map(([k,v])=>`<div><span>${esc(k.replace(/([A-Z])/g,' $1'))}</span><strong>${v}</strong></div>`).join('')}
function switchView(v){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${v}`));document.querySelectorAll('#navigation button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('page-title').textContent=titles[v];$('breadcrumb').textContent=`Nuvrion / ${titles[v]}`}
document.addEventListener('click',e=>{const checkbox=e.target.closest('[data-select-bulk],#inventory-select-all');if(!checkbox)return;e.stopImmediatePropagation();if(checkbox.id==='inventory-select-all'){document.querySelectorAll('[data-select-bulk]').forEach(item=>checkbox.checked?state.bulkSelection.add(item.dataset.selectBulk):state.bulkSelection.delete(item.dataset.selectBulk))}else checkbox.checked?state.bulkSelection.add(checkbox.dataset.selectBulk):state.bulkSelection.delete(checkbox.dataset.selectBulk);renderInventory()},true);
document.addEventListener('click',async e=>{const button=e.target.closest('[data-bulk-operation]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const operation=button.dataset.bulkOperation,labels={start:'Power on',stop:'Shut down',pause:'Suspend',restart:'Restart'},label=labels[operation]??operation,targets=state.resources.filter(resource=>state.bulkSelection.has(resource.id)&&vmHasOperation(resource,operation));if(!targets.length)return notice(`None of the selected VMs can ${label.toLowerCase()}.`,'error');if(!window.confirm(`${label} ${targets.length} selected virtual machine${targets.length===1?'':'s'}?`))return;button.disabled=true;const results=await Promise.allSettled(targets.map(resource=>api(`/resources/${resource.id}/operations`,{method:'POST',headers:{'idempotency-key':crypto.randomUUID()},body:JSON.stringify({operation})})));const failed=results.filter(result=>result.status==='rejected').length;state.bulkSelection.clear();await load();notice(failed?`${targets.length-failed} completed; ${failed} failed to queue.`:`${label} queued for ${targets.length} virtual machine${targets.length===1?'':'s'}.`,failed?'error':'success')},true);
document.addEventListener('click',e=>{const refresh=e.target.closest('[data-refresh-vms]'),edit=e.target.closest('[data-edit-vm]'),actions=e.target.closest('[data-vm-actions]');if(refresh){e.preventDefault();refreshProviders();return}if(edit){e.preventDefault();const resource=state.resources.find(item=>item.id===edit.dataset.editVm),current=localStorage.getItem(`nuvrion.vm.notes.${resource.id}`)??'',notes=window.prompt(`Edit Nuvrion notes for ${resource.name}. Provider hardware changes remain provider-controlled.`,current);if(notes!==null){localStorage.setItem(`nuvrion.vm.notes.${resource.id}`,notes);renderInventory();notice(`Notes updated for ${resource.name}.`)}return}if(actions){e.preventDefault();const count=state.selectedResourceId?1:state.bulkSelection.size;window.alert(`${count} VM${count===1?'':'s'} selected. Available lifecycle actions are shown in the toolbar; unavailable provider operations are disabled.`)}},true);
document.addEventListener('click',e=>{const selection=e.target.closest('[data-select-resource]');if(!selection)return;e.preventDefault();e.stopImmediatePropagation();state.selectedResourceId=selection.dataset.selectResource;state.selectedResourceSource=selection.closest('#vm-sidebar-list')?'sidebar':'table';switchView('inventory');renderInventory();const resource=state.resources.find(item=>item.id===state.selectedResourceId);if(resource){$('page-title').textContent=resource.name;$('breadcrumb').textContent=`Nuvrion / Virtual machines / ${resource.name}`}},true);
document.addEventListener('click',e=>{const inventoryRoot=e.target.closest('button[data-view="inventory"]');if(!inventoryRoot)return;e.preventDefault();e.stopImmediatePropagation();state.selectedResourceId=null;state.selectedResourceSource=null;switchView('inventory');renderInventory()},true);
document.addEventListener('click',e=>{const hostTerminal=e.target.closest('[data-host-terminal]');if(!hostTerminal)return;e.preventDefault();e.stopImmediatePropagation();openHostTerminal(hostTerminal.dataset.hostTerminal)},true);
document.addEventListener('click',async e=>{const button=e.target.closest('[data-ack-alert]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();try{await api(`/connection-alerts/${button.dataset.ackAlert}/acknowledge`,{method:'POST'});notice('Connection alert acknowledged.');await load()}catch(error){notice(error.message,'error')}},true);
document.addEventListener('click',async e=>{const save=e.target.closest('[data-user-save]'),sessions=e.target.closest('[data-user-sessions]'),recovery=e.target.closest('[data-user-recovery]'),id=save?.dataset.userSave??sessions?.dataset.userSessions??recovery?.dataset.userRecovery;if(!id)return;e.preventDefault();e.stopImmediatePropagation();const user=state.users.find(item=>item.id===id),row=e.target.closest('[data-user-row]');try{if(save){const status=row.querySelector('[data-user-status]').value,role=row.querySelector('[data-user-role]').value,result=await api(`/users/${id}`,{method:'PATCH',headers:{'if-match':`"${user.rowVersion}"`},body:JSON.stringify({status,roles:[role]})});if(id===state.user.id){state.user=result;showApp()}notice(user.status==='pending'?`${user.username} approved.`:`${user.username} updated.`)}else if(sessions){if(!window.confirm(`Revoke every active session for ${user.username}?`))return;const result=await api(`/users/${id}/revoke-sessions`,{method:'POST'});notice(`${result.revoked} session${result.revoked===1?'':'s'} revoked for ${user.username}.`)}else{if(!window.confirm(`Generate a new recovery code for ${user.username}? The prior code will stop working.`))return;const result=await api(`/users/${id}/recovery-code`,{method:'POST'});showRecoveryCode(result.recoveryCode,`New lab recovery code for ${user.username}.`)}await load()}catch(error){notice(error.message,'error');await load().catch(()=>{})}},true);
document.addEventListener('click',async e=>{const go=e.target.closest('[data-go]');if(go)switchView(go.dataset.go);const consoleButton=e.target.closest('[data-console]');if(consoleButton){const resource=state.resources.find(item=>item.id===consoleButton.dataset.console);if(resource)await openConsole(resource);return}const hostClient=e.target.closest('[data-host-client]');if(hostClient){const popup=window.open('about:blank','_blank');try{const result=await api(`/connections/${hostClient.dataset.hostClient}/host-client`,{method:'POST'});if(!popup)throw Error('Allow pop-ups for Nuvrion to open the ESXi Host Client.');popup.opener=null;popup.location.replace(result.url);notice('ESXi Host Client opened.')}catch(error){popup?.close();notice(error.message,'error')}return}const hostTerminal=e.target.closest('[data-host-terminal]');if(hostTerminal){state.terminalConnectionId=hostTerminal.dataset.hostTerminal;$('terminal-warning').showModal();return}const op=e.target.closest('[data-operation]');if(op){const r=state.resources.find(x=>x.id===op.dataset.id),capability=r.capabilities?.find(c=>c.operation===op.dataset.operation);state.pending={type:'resource',resource:r,operation:op.dataset.operation};$('confirm-title').textContent=`${state.pending.operation[0].toUpperCase()+state.pending.operation.slice(1)} ${r.name}?`;$('confirm-copy').textContent=`This will request ${capability?.providerSemantics??state.pending.operation} through ${provider(r.providerType)} and record the result in the audit trail.`;$('confirm-action').textContent=state.pending.operation;$('confirm-dialog').showModal()}const taskAction=e.target.closest('[data-task-action]');if(taskAction){const task=state.tasks.find(x=>x.id===taskAction.dataset.taskId),action=taskAction.dataset.taskAction;state.pending={type:'task',task,action};$('confirm-title').textContent=`${action[0].toUpperCase()+action.slice(1)} this task?`;$('confirm-copy').textContent=action==='reconcile'?'Nuvrion will perform read-only provider discovery and complete the task only if the requested final state is confirmed.':action==='retry'?'The failed operation will be queued for a new provider attempt.':'The task will be cancelled only if it is still queued and has not reached the provider.';$('confirm-action').textContent=action;$('confirm-dialog').showModal()}const testButton=e.target.closest('[data-test-connection]');if(testButton)try{await api(`/connections/${testButton.dataset.testConnection}/test`,{method:'POST'});notice('Connection test succeeded.');await load()}catch(x){notice(x.message,'error')}const d=e.target.closest('[data-discover]');if(d)try{await api(`/connections/${d.dataset.discover}/discover`,{method:'POST'});notice('Discovery completed successfully.');await load()}catch(x){notice(x.message,'error')}});
$('console-ctrl-alt-del').onclick=()=>{state.console?.sendCtrlAltDel();state.console?.focus()};$('console-send-key').onclick=()=>sendConsoleSpecialKey($('console-key').value);$('console-scale').onclick=()=>{if(!state.console)return;state.console.scaleViewport=!state.console.scaleViewport;$('console-scale').textContent=state.console.scaleViewport?'Actual size':'Fit to window';state.console.focus()};$('console-fullscreen').onclick=async()=>{try{await toggleConsoleFullscreen();state.console?.focus()}catch(error){notice(error.message,'error')}};document.addEventListener('fullscreenchange',syncConsoleFullscreenButton);document.addEventListener('webkitfullscreenchange',syncConsoleFullscreenButton);$('console-reconnect').onclick=()=>{const resource=state.consoleResource;if(!resource)return;state.console?.disconnect();state.console=null;$('console-screen').replaceChildren();openConsole(resource)};$('console-close').onclick=()=>{$('console-dialog').close()};$('console-dialog').addEventListener('close',()=>{state.console?.disconnect();state.console=null;state.consoleResource=null;setConsoleControls(false);$('console-screen').replaceChildren()});
$('terminal-warning').addEventListener('close',()=>{const credential={username:$('terminal-username').value,password:$('terminal-password').value};$('terminal-password').value='';if($('terminal-warning').returnValue==='confirm'&&state.terminalConnectionId&&credential.username&&credential.password)openHostTerminal(state.terminalConnectionId,credential);else credential.password='';state.terminalConnectionId=null});$('terminal-close').onclick=()=>$('terminal-dialog').close();$('terminal-dialog').addEventListener('close',()=>{window.removeEventListener('resize',state.terminalResize);state.terminal?.socket?.close();state.terminal?.terminal?.dispose();state.terminal=null;state.terminalResize=null;$('terminal-screen').replaceChildren()});
$('confirm-dialog').addEventListener('close',async()=>{if($('confirm-dialog').returnValue!=='confirm'||!state.pending)return;try{if(state.pending.type==='task'){await api(`/tasks/${state.pending.task.id}/${state.pending.action}`,{method:'POST'});notice(`Task ${state.pending.action} completed.`);}else{await api(`/resources/${state.pending.resource.id}/operations`,{method:'POST',headers:{'idempotency-key':crypto.randomUUID()},body:JSON.stringify({operation:state.pending.operation})});notice(`${state.pending.operation} operation accepted.`);}await new Promise(r=>setTimeout(r,150));await load()}catch(e){notice(e.message,'error')}finally{state.pending=null}});

$('login-form').addEventListener('submit',async e=>{e.preventDefault();$('login-error').textContent='';try{const result=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});state.csrf=result.csrfToken;state.user=result.user;showApp();await load()}catch{$('login-error').textContent='The username or password is incorrect.'}});$('navigation').addEventListener('click',e=>{const b=e.target.closest('button');if(b)switchView(b.dataset.view)});$('refresh').onclick=refreshProviders;$('inventory-refresh').onclick=refreshProviders;$('inventory-search').oninput=renderInventory;$('inventory-state').onchange=renderInventory;$('show-connection-form').onclick=()=>{$('connection-form').hidden=false;$('show-connection-form').hidden=true};$('cancel-connection').onclick=()=>{$('connection-form').hidden=true;$('show-connection-form').hidden=false};
$('connection-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),providerType=f.get('providerType'),mock=Boolean(f.get('mock')),credential=providerType==='aws'?{accessKeyId:f.get('username'),secretAccessKey:f.get('password'),sessionToken:f.get('sessionToken')||undefined}:providerType==='azure'?{tenantId:f.get('tenantId'),clientId:f.get('username'),clientSecret:f.get('password')}:{username:f.get('username'),password:f.get('password')},configuration=mock?{adapter:'mock'}:providerType==='aws'?{region:f.get('region')}:providerType==='azure'?{subscriptionId:f.get('subscriptionId')}:{ };try{await api('/connections',{method:'POST',body:JSON.stringify({name:f.get('name'),providerType,connectionType:f.get('connectionType'),endpointUri:f.get('endpointUri')||null,credential,configuration})});e.currentTarget.reset();$('connection-form').hidden=true;$('show-connection-form').hidden=false;notice('Connection saved. Credentials were encrypted.');await load()}catch(x){notice(x.message,'error')}});api('/auth/me').then(async me=>{state.csrf=me.csrfToken;state.user=me.user;showApp();await load()}).catch(showLogin);setInterval(()=>{if(!$('application').hidden)load().catch(()=>{})},10000);
